-- #46 시장별 근거 글과 커뮤니티 목록 (ADR-0069 decision 2 #45, decision 3 #37-2, decision 5;
-- ADR-0073). Generated by `drizzle-kit generate`, then hand-edited where marked: two blocks before
-- the statements that need them (the trigram extension before its index, the public id's function
-- before the column whose default calls it) and the tail. The snapshot is as generated.
--
-- - posts: one row per 근거 글 on one market — the optional title, the normalised body (a document,
--   never HTML), its text without formatting and its images, derived when written; '수정됨', the
--   author's deletion and an operator's hiding as times. A generated `search_text` (title and text)
--   carries the community search through a trigram index.
-- - post_revisions: every version an edit replaced, for operators only (append-only below).
-- - media_objects: the images the API received, checked, converted and stored in object storage;
--   post_images: which post an image belongs to (one post per image).
-- - media_deletions: the key of every object still in the store after its upload's row went (the
--   orphan clean-up) or that the API stored for an upload whose row it could not write and could
--   not remove right away, until the store has removed it — retried on later runs, never dropped.
-- - profiles.public_id: the account's public id, what public answers name a person by instead of
--   the account id — drawn by gen_public_id() for every existing and every new profile.
CREATE TABLE "media_deletions" (
	"storage_key" varchar(160) PRIMARY KEY NOT NULL,
	"queued_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"attempts" integer DEFAULT 0 NOT NULL,
	"next_attempt_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"last_error" text,
	CONSTRAINT "media_deletions_attempts_check" CHECK ("media_deletions"."attempts" >= 0)
);
--> statement-breakpoint
CREATE TABLE "media_objects" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"owner_id" text NOT NULL,
	"kind" varchar(16) NOT NULL,
	"storage_key" varchar(160) NOT NULL,
	"content_type" varchar(32) NOT NULL,
	"byte_size" integer NOT NULL,
	"width" integer NOT NULL,
	"height" integer NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"attached_at" timestamp (3) with time zone,
	CONSTRAINT "media_objects_storage_key_unique" UNIQUE("storage_key"),
	CONSTRAINT "media_objects_kind_check" CHECK ("media_objects"."kind" IN ('post_image')),
	CONSTRAINT "media_objects_content_type_check" CHECK ("media_objects"."content_type" IN ('image/jpeg', 'image/png', 'image/webp', 'image/gif')),
	CONSTRAINT "media_objects_size_check" CHECK ("media_objects"."byte_size" > 0 AND "media_objects"."width" > 0 AND "media_objects"."height" > 0)
);
--> statement-breakpoint
