-- Hand-edited: the public id's generator, before the column whose default calls it (#37-2: a short
-- public id apart from the account id). Ten of the 32 characters of PUBLIC_ID_ALPHABET in
-- @buddha/shared (no 0/o, 1/i), at random: not a secret, only never the account id and never
-- reused. VOLATILE, so the ADD COLUMN below draws one per existing row and every INSERT draws its
-- own. A collision (one in ~10^15 per pair) is a unique violation, which the sign-up trigger's
-- retry (create_profile_for_user, migration 0032) answers with another draw.
CREATE FUNCTION gen_public_id() RETURNS varchar
LANGUAGE sql VOLATILE AS $$
  SELECT string_agg(substr('23456789abcdefghjklmnpqrstuvwxyz', 1 + floor(random() * 32)::integer, 1), '')
    FROM generate_series(1, 10);
$$;--> statement-breakpoint
